13: /** Paper-compatible lifecycle for writable-book input without using Player.openBook. */
14: public final class BookInputSupport {
15:   private static final int INPUT_SLOT = 0;
16:   private static final Map<UUID, BookSession> PREVIOUS_HANDS = new ConcurrentHashMap<>();
17: 
18:   private record BookSession(int selectedSlot, ItemStack selectedItem, ItemStack inputSlotItem) {}
19: 
20:   private BookInputSupport() {}
21: 
22:   public static void prepare(Player player, String title, String initialPage) {
23:     // Retire an interrupted input attempt before replacing its temporary book.
24:     restore(player);
25:     int selectedSlot = player.getInventory().getHeldItemSlot();
26:     ItemStack selectedItem = cloneItem(player.getInventory().getItem(selectedSlot));
27:     ItemStack inputSlotItem = cloneItem(player.getInventory().getItem(INPUT_SLOT));
28:     PREVIOUS_HANDS.put(
29:         player.getUniqueId(), new BookSession(selectedSlot, selectedItem, inputSlotItem));
30:     ItemStack book = new ItemStack(Material.WRITABLE_BOOK);
31:     BookMeta meta = (BookMeta) book.getItemMeta();
32:     if (meta != null) {
33:       meta.setTitle(title);
34:       meta.setAuthor("StarCore");
35:       meta.addPage(initialPage == null ? "" : initialPage);
36:       book.setItemMeta(meta);
37:     }
38:     player.closeInventory();
39:     player.getInventory().setHeldItemSlot(INPUT_SLOT);
40:     player.getInventory().setItemInMainHand(book);
41:     player.updateInventory();
42:     player.sendActionBar(Component.text("右键打开输入书本，填写内容后签名确认。", NamedTextColor.YELLOW));
43:   }
44: 
45:   public static void restore(Player player) {
46:     BookSession previous = PREVIOUS_HANDS.remove(player.getUniqueId());
47:     if (previous != null) {
48:       player.getInventory().setItem(INPUT_SLOT, previous.inputSlotItem());
49:       if (previous.selectedSlot() != INPUT_SLOT) {
50:         player.getInventory().setItem(previous.selectedSlot(), previous.selectedItem());
51:         player.getInventory().setHeldItemSlot(previous.selectedSlot());
52:       }
53:       player.updateInventory();
54:     }
55:   }
56: 
57:   public static void clear(Player player) {
58:     // Quit handlers call clear before Bukkit persists the departing player's inventory.
59:     restore(player);
60:   }
